python
def frequencyFilesBossReceipt(readings):
    a=readings
    out=[]
    counts={}
    for x in a: counts[x]=counts.get(x,0)+1
    for x in sorted(counts): out.append(counts[x])
    return sum((i+1)*x for i,x in enumerate(out))


java
class Solution {
  public int frequencyFilesBossReceipt(int[] readings) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {Map<Integer,Integer>counts=new TreeMap<>();for(int x:a)counts.merge(x,1,Integer::sum);out.addAll(counts.values());}
    int answer=0;for(int i=0;i<out.size();i++)answer+=(i+1)*out.get(i);return answer;
  }
}
